//! Differential IIT 4.0 (2026) intrinsic-information primitive parity.
//!
//! Reference values are generated by the pinned PyPhi 2.0.0rc4 Fig. 1A
//! fixed-state dual-formalism artifact. This qualifies Eq. 13's fixed-state
//! intrinsic-information operand only: not MIP selection or the post-MIP cap.

use symthaea_iit::{
    BinaryCausalModel, CausalDirection, Iit4SystemIntrinsicInformation, Iit4SystemState,
    SparseBinaryCausalModel, SparseMechanismCpt, SystemPhiError,
};

const STATE: [bool; 3] = [false, true, true];
const CANDIDATE: [usize; 3] = [0, 1, 2];
const SPECIFIED: Iit4SystemState = Iit4SystemState {
    cause_specified_state: vec![true, false, false],
    effect_specified_state: vec![true, false, false],
};

const TPM: [[f64; 3]; 8] = [
    [0.11920292202211757, 0.7685247834990178, 0.16798161486607552],
    [0.026596993576865863, 0.9988874639671398, 0.5],
    [0.973403006423134, 0.40131233988754816, 0.16798161486607552],
    [0.8807970779778823, 0.9945137011005495, 0.5],
    [0.11920292202211757, 0.0054862988994504045, 0.5],
    [0.026596993576865863, 0.5986876601124519, 0.8320183851339245],
    [0.973403006423134, 0.0011125360328603216, 0.5],
    [0.8807970779778823, 0.23147521650098227, 0.8320183851339245],
];

fn dense_model() -> BinaryCausalModel {
    let probabilities = TPM.iter().flat_map(|row| row.iter().copied()).collect();
    let connectivity = vec![
        true, true, true,
        true, true, false,
        false, true, true,
    ];
    BinaryCausalModel::new(3, probabilities, connectivity).unwrap()
}

fn sparse_model() -> SparseBinaryCausalModel {
    // Parent units are ascending; the first parent is the local row LSB.
    let target_a = [TPM[0][0], TPM[1][0], TPM[2][0], TPM[3][0]];
    let target_b = TPM.iter().map(|row| row[1]).collect::<Vec<_>>();
    // Target C depends on A and C, so B's two rows are identical.
    let target_c = [TPM[0][2], TPM[1][2], TPM[4][2], TPM[5][2]];
    SparseBinaryCausalModel::new(
        3,
        vec![
            SparseMechanismCpt::new(0, vec![0, 1], target_a.to_vec()).unwrap(),
            SparseMechanismCpt::new(1, vec![0, 1, 2], target_b).unwrap(),
            SparseMechanismCpt::new(2, vec![0, 2], target_c.to_vec()).unwrap(),
        ],
    )
    .unwrap()
}

fn assert_close(field: &str, actual: f64, expected: f64) {
    assert!(actual.is_finite(), "{field} must be finite, got {actual}");
    assert!(
        (actual - expected).abs() <= 2.0e-9,
        "{field}: actual={actual:.15}, expected={expected:.15}",
    );
}

fn assert_pyphi_fig1a(result: Iit4SystemIntrinsicInformation) {
    assert_close(
        "cause intrinsic specification",
        result.cause_intrinsic_specification,
        0.7187494213884811,
    );
    assert_close(
        "effect intrinsic specification",
        result.effect_intrinsic_specification,
        0.8417962778503332,
    );
    assert_close(
        "cause intrinsic differentiation",
        result.cause_intrinsic_differentiation,
        1.2684790491435602,
    );
    assert_close(
        "effect intrinsic differentiation",
        result.effect_intrinsic_differentiation,
        1.0404968081180057,
    );
    assert_close(
        "cause selected-state probability",
        result.cause_state_probability,
        2.0_f64.powf(-1.2684790491435602),
    );
    assert_close(
        "effect selected-state probability",
        result.effect_state_probability,
        2.0_f64.powf(-1.0404968081180057),
    );
    assert_close(
        "system intrinsic information",
        result.intrinsic_information,
        0.7187494213884811,
    );
}

#[test]
fn dense_iit4_2026_intrinsic_information_matches_pinned_pyphi_fig1a() {
    let result = dense_model()
        .system_intrinsic_information_iit4_2026(
            &CANDIDATE,
            &STATE,
            &SPECIFIED,
            12,
        )
        .unwrap();
    assert_pyphi_fig1a(result);
}

#[test]
fn sparse_iit4_2026_intrinsic_information_matches_pinned_pyphi_fig1a_and_dense() {
    let result = sparse_model()
        .system_intrinsic_information_iit4_2026(
            &CANDIDATE,
            &STATE,
            &SPECIFIED,
            12,
            1 << 16,
        )
        .unwrap();
    assert_pyphi_fig1a(result);

    let dense = dense_model()
        .system_intrinsic_information_iit4_2026(
            &CANDIDATE,
            &STATE,
            &SPECIFIED,
            12,
        )
        .unwrap();
    assert_close(
        "dense/sparse ii(s)",
        result.intrinsic_information,
        dense.intrinsic_information,
    );
    assert_close(
        "dense/sparse cause differentiation",
        result.cause_intrinsic_differentiation,
        dense.cause_intrinsic_differentiation,
    );
    assert_close(
        "dense/sparse effect differentiation",
        result.effect_intrinsic_differentiation,
        dense.effect_intrinsic_differentiation,
    );
}

#[test]
fn dense_and_sparse_reject_non_maximizing_fixed_cause_state() {
    let wrong = Iit4SystemState {
        cause_specified_state: vec![false, false, false],
        effect_specified_state: vec![true, false, false],
    };
    assert!(matches!(
        dense_model().system_intrinsic_information_iit4_2026(
            &CANDIDATE, &STATE, &wrong, 12,
        ),
        Err(SystemPhiError::SpecifiedStateNotIntrinsicMaximizer {
            direction: CausalDirection::Cause
        })
    ));
    assert!(matches!(
        sparse_model().system_intrinsic_information_iit4_2026(
            &CANDIDATE, &STATE, &wrong, 12, 1 << 16,
        ),
        Err(SystemPhiError::SpecifiedStateNotIntrinsicMaximizer {
            direction: CausalDirection::Cause
        })
    ));
}
